-- Rob Units: de rest van het verhuurassortiment (6650/6700, 8200, 8300, 10.100, 10.150, 5000 en de sanitaire units),
-- met deuren en ramen uit de grondplannen op robunits.be (gemeten op het plan, ± 5 cm). Kleine ramen (toilet, douche) hoog in de wand.
insert into maps.bibliotheek (organisatie_id, naam, categorie, tekenwijze, breedte_m, diepte_m, eenheid_m, hoogte_m, omtrek, stijl, icoon, standaardlaag, leverancier, leverancier_id, eigenschappen, varianten, actief, familie)
select b.organisatie_id, n.naam, b.categorie, b.tekenwijze, n.br, n.di, b.eenheid_m, b.hoogte_m, null, b.stijl, b.icoon, b.standaardlaag, b.leverancier, b.leverancier_id,
  (b.eigenschappen - 'gevel' - 'tekening_ref' - 'inrichting') || jsonb_build_object('gevel', n.gevel, 'omschrijving', n.oms, 'subgroep', n.sub, 'stapelbaar', n.st), b.varianten, true, b.familie
from maps.bibliotheek b, (values
 ('Schakelcontainer 6 × 3 m · met gang, deur links (Rob 6650)', 3, 6, 'Kantoor', 3, 'Rob Units schakelcontainer 6650: open ruimte met gang, open aan één lange zijde. Enkel te koppelen met 6700 tot een blok van 6 × 6 m.', '[{"zijde": "V", "soort": "deur", "van": 1.93, "breedte": 0.9}, {"zijde": "V", "soort": "raam", "van": 0.2, "breedte": 1.55}, {"zijde": "A", "soort": "raam", "van": 0.37, "breedte": 2.1}]'::jsonb),
